/** Sterile packs (the stock) — GET /api/v1/cssd/packs (who may call: holders of cssd.view or cssd.operate or cssd.manage or cssd.pack.use). */
export function listPacks(query?: { status?: "Quarantined" | "Available" | "Issued" | "Used" | "Expired" | "Failed" | "Recalled" | null; set_type_id?: number | null; ward_id?: number | null; ot_id?: number | null; expiring_only?: boolean; limit?: number }): Promise<PackOut[]> {
  return api<PackOut[]>("GET", withQuery(`/cssd/packs`, query), undefined);
}

/** Issue sterile packs to a ward or theatre — POST /api/v1/cssd/packs/issue (who may call: holders of cssd.operate). */
export function issueCssdPacks(body: PackIssueIn): Promise<PackOut[]> {
  return api<PackOut[]>("POST", `/cssd/packs/issue`, body);
}

/** One sterile pack (scan its label) — GET /api/v1/cssd/packs/{pack_code} (who may call: holders of cssd.view or cssd.operate or cssd.manage or cssd.pack.use). */
export function getPack(pack_code: string): Promise<PackOut> {
  return api<PackOut>("GET", `/cssd/packs/${pack_code}`, undefined);
}

/** Live bed matrix (counts per ward + optional bed list) — GET /api/v1/beds/matrix (who may call: holders of ipd.bed.view or cssd.operate or infection.control.manage or complaint.manage or incident.view or facility.drill.manage or roster.manage.all or facility.equipment.manage or pharmacy.storage.record). */
export function bedMatrix(query?: { include_beds?: boolean }): Promise<BedMatrixOut> {
  return api<BedMatrixOut>("GET", withQuery(`/beds/matrix`, query), undefined);
}

/** All theaters (incl. out-of-service) — GET /api/v1/ot/theaters (who may call: holders of ot.status.view or cssd.operate or facility.equipment.manage). */
export function theaters(): Promise<TheaterOut[]> {
  return api<TheaterOut[]>("GET", `/ot/theaters`, undefined);
}
